function name(english, language) {
    const table = names[language];
    return table && table[english] ? table[english] : english;
}

function labels(layout, variant) {
    let position = index[variant ? layout + "(" + variant + ")" : layout];
    if (position === undefined) {
        position = index[layout];
    }
    if (position === undefined) {
        position = index["us"];
    }
    const levels = maps[position].split("\n").map(level => level.split("\t"));
    const result = {};
    let key = 0;
    for (const row of rows) {
        for (const code of row) {
            result[code] = [levels[0][key], levels[1][key]];
            ++key;
        }
    }
    return result;
}
